/* Separate QR158-03 entrance; existing maintenance persistence and permissions remain authoritative. */
(()=>{
const words={oilConfirm:['確認本次更換／測試完成','Confirm replacement / test complete','Confirmar cambio / prueba','Xác nhận hoàn tất thay / thử'],oilReplacement:['QR158-03 油品更換記錄表','QR158-03 Oil replacement record','QR158-03 Registro de cambio de aceite','QR158-03 Hồ sơ thay dầu'],oilHelp:['依原表週期執行，點月份符號填寫實際更換／測試日期、更換人與備註。空心＝排定，實心＝已確認完成；草稿不算完成。','Follow the original schedule. Select a month symbol to enter the actual replacement/test date, performer and notes. Hollow = planned; filled = confirmed complete. Drafts are not complete.','Siga el programa original. Seleccione un símbolo mensual para registrar fecha real, responsable y notas. Vacío = programado; lleno = confirmado. Los borradores no están completos.','Thực hiện theo lịch gốc. Chọn ký hiệu tháng để nhập ngày thay/thử thực tế, người thực hiện và ghi chú. Rỗng = kế hoạch; đặc = đã xác nhận. Nháp chưa được tính hoàn thành.'],oilReplacer:['更換人','Replacer','Responsable del cambio','Người thay dầu'],oilManager:['主管簽名','Manager signature','Firma del supervisor','Chữ ký quản lý'],oilNotes:['備註','Remarks','Observaciones','Ghi chú'],oilAdd:['新增更換／測試紀錄','Add replacement / test record','Añadir cambio / prueba','Thêm hồ sơ thay / thử'],oilPrint:['列印年度表單','Print annual sheet','Imprimir hoja anual','In biểu mẫu năm'],oilEmpty:['本部門尚未分配油品更換表，請至「設備點檢表分配與啟用」設定。','No oil form is assigned. Configure it in Equipment form assignment and activation.','No hay formulario de aceite asignado. Configúrelo en Asignación y activación.','Chưa phân công biểu mẫu thay dầu. Thiết lập tại Phân công và kích hoạt biểu mẫu.'],oilPaperSign:['主管欄供列印後簽名；各次紀錄的確認狀態另於月份格顯示。','Manager fields are for signatures after printing; each record’s confirmation status is shown in its month cell.','Las firmas del supervisor se completan tras imprimir; el estado aparece en cada mes.','Ô quản lý dùng ký sau khi in; trạng thái xác nhận hiển thị trong ô tháng.'],oilOriginal:['原始表單','Original form','Formulario original','Biểu mẫu gốc']};
for(const[k,v]of Object.entries(words))translations[k]=Object.fromEntries(['zh','en','es','vi'].map((l,i)=>[l,v[i]]));
let context='',dept='',equipment='',year=Number(inspectionDay().slice(0,4));
const syms={W:['○','●'],M:['△','▲'],Q:['◇','◆'],Y:['□','■'],E:['E','✓']};
function pairs(){const forms=new Map(data.forms.filter(f=>f.kind==='maintenance'&&isOilReplacementForm(f)).map(f=>[f.id,f]));return data.equipment.filter(e=>!e.archived_at&&accessCan(e.department_id,'maintenance')).flatMap(e=>{const a=data.assignments.find(a=>a.equipment_id===e.id&&a.kind==='maintenance'),f=forms.get(a?.form_id);return f?[{e,f}]:[];});}
const priorContent=renderContent;renderContent=function(){if(view!=='oilReplacement')return priorContent();if(!profile||!activeCountry||!accessAny('maintenance')){$('#content').innerHTML=txt('accessNoRights');return;}draw();};
const priorRender=render;render=function(){priorRender();if(!profile||!activeCountry||!accessAny('maintenance'))return;const parent=$('.side details[data-section="field"] .nav-section-items');if(!parent)return;const b=document.createElement('button');b.className='nav'+(view==='oilReplacement'?' active':'');b.dataset.view='oilReplacement';b.innerHTML='▶ '+txt('oilReplacement');b.onclick=()=>{view='oilReplacement';render();};const anchor=parent.querySelector('[data-view="qr04"]');if(anchor)anchor.after(b);else parent.append(b);if(view==='oilReplacement')parent.parentElement.open=true;};
function draw(){
 const k=[activeCountry,countryGeneration,profile.account_id].join(':');if(context!==k){context=k;dept='';equipment='';year=Number(inspectionDay().slice(0,4));}
 const all=pairs(),departments=data.departments.filter(d=>all.some(p=>p.e.department_id===d.id));
 if(!departments.some(d=>d.id===dept)){dept=departments.find(d=>d.id===profile.department_id)?.id||departments[0]?.id||'';equipment='';}
 const choices=all.filter(p=>p.e.department_id===dept);if(!choices.some(p=>p.e.id===equipment))equipment=choices[0]?.e.id||'';
 const pair=choices.find(p=>p.e.id===equipment);$('.page-title h1').innerHTML=txt('oilReplacement');
 $('#content').innerHTML=`<section class="oil-page"><p class="notice oil-toolbar">${txt('oilHelp')}</p><div class="filter-row oil-toolbar"><label>${txt('department')}<select id="oilDept" class="select">${departments.map(d=>`<option value="${esc(d.id)}" ${dept===d.id?'selected':''}>${esc(nameOf(d))}</option>`).join('')}</select></label><label>${txt('equipmentName')}<select id="oilEquipment" class="select">${choices.map(({e})=>`<option value="${esc(e.id)}" ${equipment===e.id?'selected':''}>${esc(e.equipment_code+' · '+nameOf(e))}</option>`).join('')}</select></label><label>${txt('year')}<input type="number" min="2000" max="2100" id="oilYear" class="select" value="${year}"></label><button id="oilPrint" class="btn secondary" ${pair?'':'disabled'}>${txt('oilPrint')}</button></div>${pair?paper(pair):`<p class="notice">${txt('oilEmpty')}</p>`}</section>`;
 $('#oilDept').onchange=e=>{dept=e.target.value;equipment='';draw();};$('#oilEquipment').onchange=e=>{equipment=e.target.value;draw();};$('#oilYear').onchange=e=>{const n=Number(e.target.value);if(Number.isInteger(n)&&n>=2000&&n<=2100)year=n;draw();};
 $('#oilPrint').onclick=()=>{document.body.classList.add('printing-oil');try{window.print();}finally{document.body.classList.remove('printing-oil');}};
 if(!pair)return;const {e,f}=pair;
 $$('[data-oil-add]').forEach(b=>b.onclick=()=>{if(!accessCan(e.department_id,'maintenance','create'))return;const[i,m]=b.dataset.oilAdd.split(':').map(Number);InspectionManagement.openOilMaintenance(e,f,i,m,year);});
 $$('[data-oil-record]').forEach(b=>b.onclick=()=>{const r=data.maintenanceRecords.find(r=>r.id===b.dataset.oilRecord);if(r&&r.equipment_id===e.id&&r.form_id===f.id&&accessCan(e.department_id,'maintenance'))InspectionManagement.openMaintenance(r,undefined,undefined,!accessCan(e.department_id,'maintenance','edit'));});
}
function paper({e,f}){
 const months=Array.from({length:12},(_,i)=>i+1),d=data.departments.find(d=>d.id===e.department_id),records=(data.maintenanceRecords||[]).filter(r=>r.equipment_id===e.id&&r.form_id===f.id&&r.year===year);
 const entries=(index,m)=>records.flatMap(r=>r.rows.filter(row=>row.item_index===index&&JSON.stringify(row.item.name)===JSON.stringify(f.items[index]?.name)&&row.planned_start?.slice(0,7)===year+'-'+String(m).padStart(2,'0')).map(row=>({r,row})));
 const cells=(item,i)=>months.map(m=>{const rows=entries(i,m),plan=pmDefaultSchedule(item).filter(x=>x.month===m),code=InspectionManagement.cycleCode(item.cycle.zh),canAdd=accessCan(e.department_id,'maintenance','create');return `<td>${rows.map(({r,row})=>{const c=row.cycle_code,done=r.status==='confirmed'&&!!row.completed_date;return `<button class="oil-entry ${done?'oil-done':'oil-draft'}" data-oil-record="${esc(r.id)}" title="${esc(t(r.status)+' · '+r.performer_name+' · '+(row.completed_date||''))}">${esc(syms[c]?.[done?1:0]||c)}<small>${esc(row.completed_date?.slice(5)||t('draft'))}</small></button>`;}).join('')}${!rows.length&&plan.length?`<button class="oil-plan" data-oil-add="${i}:${m}" aria-label="${esc(multilingual(item.name)+' '+year+'-'+m+' '+t('oilAdd'))}" ${canAdd?'':'disabled'}>${esc(syms[code]?.[0]||'◇')}</button>`:''}<button class="oil-add oil-toolbar" data-oil-add="${i}:${m}" aria-label="${esc(multilingual(item.name)+' '+year+'-'+m+' '+t('oilAdd'))}" ${canAdd?'':'disabled'}>＋</button></td>`;}).join('');
 const footer=(label,fn)=>`<tr class="oil-signatures"><th>${txt(label)}</th>${months.map(m=>`<td>${fn(m)}</td>`).join('')}</tr>`;
 const monthRecords=m=>records.filter(r=>r.rows.some(x=>x.planned_start?.slice(0,7)===year+'-'+String(m).padStart(2,'0')));
 return `<div class="oil-paper-scroll"><article class="oil-paper"><header><img src="/cadre-logo.png" alt="NES Limited"><h2>${txt('oilReplacement')}</h2></header><table class="oil-meta"><tbody><tr><th>${txt('department')}</th><td>${esc(nameOf(d))}</td><th>${txt('equipmentName')}</th><td>${esc(nameOf(e))}</td><th>${txt('year')}</th><td>${year}</td></tr><tr><th>${txt('machineNo')}</th><td>${esc(e.machine_no||e.equipment_code)}</td><th>${txt('propertyNo')}</th><td colspan="3">${esc(e.property_no)}</td></tr></tbody></table><table class="oil-table"><colgroup><col class="oil-item-col"><col class="oil-cycle-col">${'<col>'.repeat(12)}</colgroup><thead><tr><th>${txt('item')}</th><th>${txt('cycle')}</th>${months.map(m=>`<th>${m}<small>${txt('pmMonth')}</small></th>`).join('')}</tr></thead><tbody>${f.items.map((item,i)=>`<tr class="oil-item"><th>${esc(multilingual(item.name))}</th><td>${esc(multilingual(item.cycle))}</td>${cells(item,i)}</tr>`).join('')}${Array.from({length:3},()=>`<tr class="oil-blank">${'<td></td>'.repeat(14)}</tr>`).join('')}${footer('oilReplacer',m=>[...new Set(monthRecords(m).map(r=>r.performer_name))].map(esc).join('<br>'))}${footer('oilManager',()=>'<span class="oil-sign-space"></span>')}${footer('oilNotes',m=>[...new Set(monthRecords(m).flatMap(r=>r.rows.filter(x=>x.planned_start?.slice(0,7)===year+'-'+String(m).padStart(2,'0')).map(x=>x.note)).filter(Boolean))].map(esc).join('<br>'))}</tbody></table><p class="oil-instructions">${txt('oilHelp')}</p><p class="oil-toolbar">${txt('oilPaperSign')}</p><p class="oil-source oil-toolbar">${txt('oilOriginal')}：${esc(f.source_filename||f.form_name)}</p><div class="oil-form-code">QR158-03-A</div></article></div>${records.length?`<section class="oil-toolbar"><h3>${txt('pmRecords')}</h3>${records.map(r=>`<button class="btn secondary" data-oil-record="${esc(r.id)}">${esc(r.rows.map(x=>x.planned_start).join(' / '))} · ${esc(r.performer_name)} · ${txt(r.status)}</button>`).join(' ')}</section>`:''}`;
}
})();
